declare const process: { stdin: { setEncoding(v: string): void; once(e: string, fn: (v: string) => void): void; resume(): void; destroy(): void } };
export class Main {
    static main(): void {
        console.log("Qual é seu nome? Digite e toque em Enviar.");
        process.stdin.setEncoding("utf8");
        process.stdin.once("data", (texto: string) => {
            console.log(new Saudacao(texto.trim()).mensagem());
            process.stdin.destroy();
        });
        process.stdin.resume();
    }
}
Main.main();

