import java.util.Locale;
public class Grafico {
    public double amplitude = 100;
    private String curva(boolean seno) {
        StringBuilder pontos = new StringBuilder();
        for (int x = 20; x <= 340; x += 2) {
            if (x > 20) pontos.append(",");
            double t = (x - 20) / 320.0 * Math.PI * 4;
            double y = 200 - amplitude * (seno ? Math.sin(t) : Math.cos(t));
            pontos.append(String.format(Locale.ROOT,"[%d,%.3f]",x,y));
        }
        return "{\"type\":\"polyline\",\"color\":\"" + (seno ? "#75c7a0" : "#80aef0") + "\",\"points\":[" + pontos + "]}";
    }
    public String cena() {
        return "{\"title\":\"Seno e cosseno\",\"mode\":\"2d\",\"width\":360,\"height\":400,\"shapes\":["
            + "{\"type\":\"line\",\"x1\":20,\"y1\":200,\"x2\":340,\"y2\":200,\"color\":\"#5d7468\"},"
            + "{\"type\":\"line\",\"x1\":20,\"y1\":50,\"x2\":20,\"y2\":350,\"color\":\"#5d7468\"},"
            + curva(true) + "," + curva(false) + ","
            + "{\"type\":\"text\",\"x\":24,\"y\":32,\"text\":\"Verde: seno | Azul: cosseno\",\"color\":\"#d8e9df\",\"size\":16}]}";
    }
}

