#!/usr/bin/env python3
"""Native software viewport for line-delimited JSON scenes emitted by Java/Node."""
import argparse,json,math,os,signal,subprocess,threading,time
from pathlib import Path
import gi
gi.require_version('Gtk','4.0')
from gi.repository import Gtk,GLib,Gdk
import cairo

def color(value):
    value=value if isinstance(value,str) and len(value)==7 and value.startswith('#') else '#79b99a'
    try: return tuple(int(value[i:i+2],16)/255 for i in (1,3,5))
    except ValueError: return (.47,.72,.60)

def validate_scene(scene):
    if not isinstance(scene,dict): raise ValueError('Cena deve ser um objeto JSON')
    if scene.get('mode','2d') not in ('2d','3d'): raise ValueError('Modo de cena inválido')
    if scene.get('mode')=='3d':
        vertices=scene.get('vertices',[]); faces=scene.get('faces',[])
        if len(vertices)>2000 or len(faces)>3000: raise ValueError('Cena 3D acima do limite')
        if any(not isinstance(v,list) or len(v)!=3 or any(not isinstance(x,(int,float)) or not math.isfinite(x) for x in v) for v in vertices): raise ValueError('Vértice inválido')
        if any(not isinstance(f,list) or len(f)<3 or any(not isinstance(i,int) or not 0<=i<len(vertices) for i in f) for f in faces): raise ValueError('Face inválida')
    else:
        w,h=scene.get('width',360),scene.get('height',400)
        if not all(isinstance(v,(int,float)) and math.isfinite(v) and 0<v<=10000 for v in (w,h)): raise ValueError('Dimensão inválida')
        if len(scene.get('shapes',[]))>3000: raise ValueError('Cena 2D acima do limite')
    return scene

class View(Gtk.ApplicationWindow):
    def __init__(self,app,args):
        super().__init__(application=app,title='Trama · gráficos')
        self.set_default_size(390,640)
        self.args=args;self.scene=None;self.child=None;self.paused=False;self.closing=False
        self.angle=.35;self.tilt=-.3;self.auto=True;self.frames=0;self.last_frame=0;self.dragging=False;self.reader_failed=False
        root=Gtk.Box(orientation=Gtk.Orientation.VERTICAL,spacing=6);self.set_child(root)
        self.title=Gtk.Label(label='Carregando cena…',xalign=0,margin_start=12,margin_end=12,margin_top=10,wrap=True);root.append(self.title)
        self.area=Gtk.DrawingArea(vexpand=True,hexpand=True);self.area.set_draw_func(self.draw);root.append(self.area)
        self.status=Gtk.Label(label='Gráficos por software · toque para interagir',wrap=True,margin_start=10,margin_end=10);root.append(self.status)
        controls=Gtk.Box(spacing=6,homogeneous=True,margin_start=10,margin_end=10,margin_bottom=10);root.append(controls)
        self.pause_button=Gtk.Button(label='Pausar');self.pause_button.connect('clicked',self.pause);controls.append(self.pause_button)
        self.reset_button=Gtk.Button(label='Reiniciar vista');self.reset_button.connect('clicked',lambda b:self.reset());controls.append(self.reset_button)
        close=Gtk.Button(label='Fechar');close.connect('clicked',lambda b:self.close());controls.append(close)
        css=Gtk.CssProvider();css.load_from_data(b'window {background:#eff4f0;color:#294337;} button {min-height:44px;padding:0 8px;}')
        Gtk.StyleContext.add_provider_for_display(self.get_display(),css,600)
        drag=Gtk.GestureDrag();drag.connect('drag-begin',self.drag_begin);drag.connect('drag-update',self.drag_update);drag.connect('drag-end',lambda *a:setattr(self,'dragging',False));self.area.add_controller(drag)
        tap=Gtk.GestureClick();tap.connect('released',self.tap);self.area.add_controller(tap)
        self.connect('close-request',self.shutdown)
        GLib.timeout_add(50,self.tick)
        GLib.idle_add(self.start)
        if args.smoke: GLib.timeout_add(7000,self.smoke_timeout)
    def start(self):
        build=Path(self.args.build).resolve()
        command=['java','-cp',str(build),self.args.entry] if self.args.language=='Java' else ['node',str(build/(self.args.entry+'.js'))]
        try:
            self.child=subprocess.Popen(command,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=None)
        except OSError as ex:
            self.reader_failed=True;self.status.set_text(str(ex));print(str(ex),flush=True);return False
        def read():
            try:
                while True:
                    line=self.child.stdout.readline(1_000_001)
                    if not line: break
                    if len(line)>1_000_000: raise ValueError('Cena acima de 1 MB')
                    try:
                        scene=validate_scene(json.loads(line))
                        # Keep only the newest frame; avoid a backlog on a slow phone.
                        self.pending=scene
                    except (ValueError,TypeError,KeyError) as ex: GLib.idle_add(self.problem,str(ex))
                code=self.child.wait()
                GLib.idle_add(self.producer_done,code)
            except Exception as ex: GLib.idle_add(self.problem,str(ex))
        threading.Thread(target=read,daemon=True).start();return False
    def problem(self,text):
        if self.closing: return False
        self.reader_failed=True;self.status.set_text('Erro de cena: '+text);print('GRAPHICS_ERROR: '+text,flush=True);return False
    def producer_done(self,code):
        if self.closing: return False
        if code: self.problem('Programa terminou com código '+str(code))
        return False
    def tick(self):
        if self.closing: return False
        if hasattr(self,'pending'):
            self.scene=self.pending;del self.pending;self.frames+=1;self.last_frame=time.monotonic()
            self.set_title('Trama · '+str(self.scene.get('title','Gráficos')))
            self.title.set_text(str(self.scene.get('title','Gráficos')))
            three=self.scene.get('mode')=='3d'
            self.reset_button.set_visible(three)
            self.pause_button.set_visible(three or self.scene.get('animated',False))
            self.status.set_text('Arraste para girar · projeção 3D por software' if three else 'Animação 2D por software · use Pausar para observar' if self.scene.get('animated') else 'Gráfico 2D por software · redimensiona com a janela')
        if self.scene:
            if self.scene.get('mode')=='3d' and self.auto and not self.paused and not self.dragging: self.angle+=.025
            self.area.queue_draw()
            if self.args.smoke and self.frames>=1:
                surface=cairo.ImageSurface(cairo.FORMAT_ARGB32,360,440);self.render(cairo.Context(surface),360,440)
                if self.args.capture: surface.write_to_png(self.args.capture)
                print('GRAPHICS_SMOKE_OK: '+str(self.scene.get('title',''))+' '+self.scene.get('mode','2d'),flush=True)
                self.close();return False
        return True
    def smoke_timeout(self):
        if not self.closing: self.problem('Nenhuma cena válida recebida');self.close()
        return False
    def pause(self,b):
        self.paused=not self.paused;self.auto=not self.paused
        if self.child and self.child.poll() is None:
            try: os.kill(self.child.pid,signal.SIGSTOP if self.paused else signal.SIGCONT)
            except ProcessLookupError: pass
        b.set_label('Continuar' if self.paused else 'Pausar')
    def reset(self): self.angle=.35;self.tilt=-.3;self.auto=True
    def drag_begin(self,g,x,y): self.dragging=True;self.start_angle=self.angle;self.start_tilt=self.tilt
    def drag_update(self,g,x,y): self.angle=self.start_angle+x*.012;self.tilt=max(-1.4,min(1.4,self.start_tilt+y*.012));self.area.queue_draw()
    def tap(self,g,count,x,y):
        if self.scene and self.scene.get('interactive',False) and self.scene.get('mode')!='3d' and self.child and self.child.poll() is None:
            scale,ox,oy=self.transform(self.area.get_width(),self.area.get_height())
            try:
                self.child.stdin.write((json.dumps(dict(event='tap',x=(x-ox)/scale,y=(y-oy)/scale))+'\n').encode());self.child.stdin.flush()
            except (OSError,ValueError): pass
    def shutdown(self,*a):
        self.closing=True
        if self.child and self.child.poll() is None:
            self.child.kill()
            try: self.child.wait(timeout=2)
            except subprocess.TimeoutExpired: pass
        if self.args.smoke and (not self.scene or self.reader_failed): self.get_application().failed=True
        return False
    def transform(self,w,h):
        sw,sh=self.scene.get('width',360),self.scene.get('height',400)
        scale=min(w/sw,h/sh);return scale,(w-sw*scale)/2,(h-sh*scale)/2
    def draw(self,area,cr,w,h):
        try: self.render(cr,w,h)
        except (ValueError,TypeError,KeyError,OverflowError) as ex: self.problem(str(ex))
    def render(self,cr,w,h):
        cr.set_source_rgb(*color(self.scene.get('background','#111e18') if self.scene else '#111e18'));cr.paint()
        if not self.scene: return
        if self.scene.get('mode')=='3d': self.render_3d(cr,w,h);return
        scale,ox,oy=self.transform(w,h);cr.translate(ox,oy);cr.scale(scale,scale)
        for s in self.scene.get('shapes',[]):
            kind=s.get('type');cr.set_source_rgb(*color(s.get('color','#7fbf9f')));cr.set_line_width(s.get('stroke',2))
            if kind=='circle': cr.arc(s['x'],s['y'],s['r'],0,math.tau)
            elif kind=='rect': cr.rectangle(s['x'],s['y'],s['width'],s['height'])
            elif kind=='line': cr.move_to(s['x1'],s['y1']);cr.line_to(s['x2'],s['y2'])
            elif kind=='polyline':
                points=s.get('points',[])
                for i,p in enumerate(points):
                    if i: cr.line_to(*p)
                    else: cr.move_to(*p)
            elif kind=='text':
                cr.set_font_size(s.get('size',16));cr.move_to(s['x'],s['y']);cr.show_text(s.get('text','')[:300]);continue
            else: continue
            if s.get('fill',False): cr.fill()
            else: cr.stroke()
    def render_3d(self,cr,w,h):
        vertices=[];projected=[]
        for x,y,z in self.scene['vertices']:
            rx=x*math.cos(self.angle)+z*math.sin(self.angle);rz=-x*math.sin(self.angle)+z*math.cos(self.angle)
            ry=y*math.cos(self.tilt)-rz*math.sin(self.tilt);rz=y*math.sin(self.tilt)+rz*math.cos(self.tilt)
            vertices.append((rx,ry,rz));factor=min(w,h)*.92/max(.2,rz+5)
            projected.append((w/2+rx*factor,h/2-ry*factor))
        faces=self.scene.get('faces',[]);colors=self.scene.get('colors',['#75b99a','#6e9ac0','#c5ac6b','#a48abd'])
        if not colors: colors=['#75b99a']
        order=sorted(enumerate(faces),key=lambda item:sum(vertices[i][2] for i in item[1])/len(item[1]),reverse=True)
        for number,face in order:
            for j,i in enumerate(face):
                if j: cr.line_to(*projected[i])
                else: cr.move_to(*projected[i])
            cr.close_path();cr.set_source_rgb(*color(colors[number%len(colors)]));cr.fill_preserve();cr.set_source_rgba(.95,1,.97,.8);cr.set_line_width(1.3);cr.stroke()
        cr.set_source_rgb(.8,.9,.85);cr.set_font_size(13);cr.move_to(12,h-18);cr.show_text('Arraste para girar · Pausar para observar')

class App(Gtk.Application):
    def __init__(self,args): super().__init__(application_id=None);self.args=args;self.failed=False
    def do_activate(self): View(self,self.args).present()

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--language',choices=['Java','TypeScript'],required=True);parser.add_argument('--entry',required=True);parser.add_argument('--build',default='build');parser.add_argument('--smoke',action='store_true');parser.add_argument('--capture')
    args=parser.parse_args()
    if not args.entry.isidentifier(): parser.error('Entrada inválida')
    app=App(args);app.run([]);return 1 if app.failed else 0
if __name__=='__main__': raise SystemExit(main())

