import java.util.Locale;
public class Bola {
    public double x,y,raio=16;
    private double vx,vy;
    private String cor;
    public Bola(double x,double y,double vx,double vy,String cor) {this.x=x;this.y=y;this.vx=vx;this.vy=vy;this.cor=cor;}
    public void atualizar() {
        x+=vx;y+=vy;
        if(x<raio || x>360-raio) {vx=-vx;x=Math.max(raio,Math.min(360-raio,x));}
        if(y<50+raio || y>400-raio) {vy=-vy;y=Math.max(50+raio,Math.min(400-raio,y));}
    }
    public String forma() {return String.format(Locale.ROOT,"{\"type\":\"circle\",\"x\":%.2f,\"y\":%.2f,\"r\":%.2f,\"fill\":true,\"color\":\"%s\"}",x,y,raio,cor);}
}

