public class Mundo {
    public Bola[] bolas={new Bola(70,130,3,2,"#80cfa9"),new Bola(180,240,-2,3,"#86b7ec"),new Bola(270,320,2,-2,"#e6bd78")};
    public String cena() {
        StringBuilder shapes=new StringBuilder("{\"type\":\"text\",\"x\":20,\"y\":28,\"text\":\"Animação 2D - 20 quadros/s\",\"color\":\"#d9ebdf\",\"size\":16}");
        for(Bola bola:bolas) {bola.atualizar();shapes.append(",").append(bola.forma());}
        return "{\"title\":\"Bolas em movimento\",\"mode\":\"2d\",\"animated\":true,\"width\":360,\"height\":400,\"shapes\":["+shapes+"]}";
    }
}

