import java.util.LinkedHashMap;
import java.util.Map;

// Leitor pequeno para os objetos de entrada desta API: strings, booleanos e null.
public final class Json {
    public static String texto(String value) {
        StringBuilder out = new StringBuilder("\"");
        for (char c : value.toCharArray()) {
            switch (c) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> { if (c < 32) out.append(String.format("\\u%04x", (int)c)); else out.append(c); }
            }
        }
        return out.append('"').toString();
    }
    public static Map<String,Object> objeto(String source) { return new Parser(source).read(); }
    private static final class Parser {
        private final String source;
        private int index;
        Parser(String source) { this.source = source; }
        void spaces() { while(index < source.length() && " \r\n\t".indexOf(source.charAt(index)) >= 0) index++; }
        boolean take(char c) { spaces(); if(index < source.length() && source.charAt(index)==c) { index++; return true; } return false; }
        void need(char c) { if(!take(c)) throw new IllegalArgumentException("JSON inválido"); }
        String string() {
            need('"'); StringBuilder result = new StringBuilder();
            while(index < source.length()) {
                char c=source.charAt(index++);
                if(c=='"') return result.toString();
                if(c<32) throw new IllegalArgumentException("JSON inválido");
                if(c=='\\') {
                    if(index >= source.length()) throw new IllegalArgumentException("JSON inválido");
                    char escaped=source.charAt(index++);
                    switch(escaped) {
                        case '"', '\\', '/' -> result.append(escaped);
                        case 'b' -> result.append('\b'); case 'f' -> result.append('\f');
                        case 'n' -> result.append('\n'); case 'r' -> result.append('\r'); case 't' -> result.append('\t');
                        case 'u' -> {
                            if(index+4>source.length()) throw new IllegalArgumentException("JSON inválido");
                            result.append((char)Integer.parseInt(source.substring(index,index+4),16));index+=4;
                        }
                        default -> throw new IllegalArgumentException("JSON inválido");
                    }
                } else result.append(c);
            }
            throw new IllegalArgumentException("JSON inválido");
        }
        Map<String,Object> read() {
            Map<String,Object> result=new LinkedHashMap<>();need('{');
            if(!take('}')) {
                do {
                    String key=string();need(':');spaces();Object value;
                    if(index < source.length() && source.charAt(index)=='"') value=string();
                    else if(source.startsWith("true",index)) {value=true;index+=4;}
                    else if(source.startsWith("false",index)) {value=false;index+=5;}
                    else if(source.startsWith("null",index)) {value=null;index+=4;}
                    else throw new IllegalArgumentException("JSON inválido ou tipo não aceito");
                    if(result.containsKey(key)) throw new IllegalArgumentException("Campo duplicado");
                    result.put(key,value);
                } while(take(','));
                need('}');
            }
            spaces();if(index != source.length()) throw new IllegalArgumentException("JSON inválido");return result;
        }
    }
}

