import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

// Dados em memória: reiniciar a API esvazia a lista.
public class ServicoTarefas {
    private final Map<Integer,Tarefa> tarefas=new LinkedHashMap<>();
    private int proximoId=1;
    public synchronized List<Tarefa> listar() { return new ArrayList<>(tarefas.values()); }
    public synchronized Tarefa criar(String titulo) {
        Tarefa tarefa=new Tarefa(proximoId++,titulo);tarefas.put(tarefa.id,tarefa);return tarefa;
    }
    public synchronized Tarefa atualizar(int id, boolean concluida) {
        Tarefa tarefa=tarefas.get(id);if(tarefa!=null) tarefa.concluida=concluida;return tarefa;
    }
    public synchronized boolean excluir(int id) { return tarefas.remove(id)!=null; }
}

