import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class ServidorApi {
    private final ServicoTarefas servico;
    public ServidorApi(ServicoTarefas servico) { this.servico=servico; }
    private void responder(HttpExchange request,int status,String json) throws IOException {
        byte[] bytes=json.getBytes(StandardCharsets.UTF_8);
        request.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");
        request.getResponseHeaders().set("Cache-Control","no-store");
        request.getResponseHeaders().set("X-Content-Type-Options","nosniff");
        request.sendResponseHeaders(status,status==204 ? -1 : bytes.length);
        if(status!=204) request.getResponseBody().write(bytes);
        request.close();
    }
    private Map<String,Object> corpo(HttpExchange request) throws IOException {
        byte[] data=request.getRequestBody().readNBytes(8193);
        if(data.length>8192) throw new BodyTooLarge();
        return Json.objeto(new String(data,StandardCharsets.UTF_8));
    }
    private static final class BodyTooLarge extends RuntimeException {}
    private void atender(HttpExchange request) throws IOException {
        String method=request.getRequestMethod(),path=request.getRequestURI().getPath();
        try {
            if((path.equals("/") || path.equals("/saude")) && method.equals("GET")) {
                responder(request,200,path.equals("/saude") ? "{\"status\":\"ok\"}" : "{\"api\":\"Tarefas Trama\",\"rotas\":[\"GET /saude\",\"GET /tarefas\",\"POST /tarefas\",\"PATCH /tarefas/{id}\",\"DELETE /tarefas/{id}\"]}");return;
            }
            boolean collection=path.equals("/tarefas"),item=path.matches("/tarefas/[1-9][0-9]{0,8}");
            if(!collection && !item) {responder(request,404,"{\"erro\":\"Rota não encontrada\"}");return;}
            if(collection && method.equals("GET")) {
                responder(request,200,servico.listar().stream().map(Tarefa::json).collect(Collectors.joining(",","[","]")));return;
            }
            if((collection && method.equals("POST")) || (item && method.equals("PATCH"))) {
                String contentType=request.getRequestHeaders().getFirst("Content-Type");
                if(contentType==null || !contentType.split(";",2)[0].trim().equalsIgnoreCase("application/json")) {responder(request,415,"{\"erro\":\"Use Content-Type application/json\"}");return;}
                Map<String,Object> body=corpo(request);
                if(collection) {
                    if(body.size()!=1 || !(body.get("titulo") instanceof String titulo) || titulo.trim().isEmpty() || titulo.trim().length()>120) throw new IllegalArgumentException("Informe apenas titulo: texto de 1 a 120 caracteres");
                    Tarefa tarefa=servico.criar(((String)body.get("titulo")).trim());request.getResponseHeaders().set("Location","/tarefas/"+tarefa.id);responder(request,201,tarefa.json());return;
                }
                if(body.size()!=1 || !(body.get("concluida") instanceof Boolean)) throw new IllegalArgumentException("Informe apenas concluida: true ou false");
                Tarefa tarefa=servico.atualizar(Integer.parseInt(path.substring(9)),(Boolean)body.get("concluida"));
                responder(request,tarefa==null ? 404 : 200,tarefa==null ? "{\"erro\":\"Tarefa não encontrada\"}" : tarefa.json());return;
            }
            if(item && method.equals("DELETE")) {
                boolean removed=servico.excluir(Integer.parseInt(path.substring(9)));responder(request,removed ? 204 : 404,removed ? "" : "{\"erro\":\"Tarefa não encontrada\"}");return;
            }
            request.getResponseHeaders().set("Allow",collection ? "GET, POST" : "PATCH, DELETE");responder(request,405,"{\"erro\":\"Método não permitido\"}");
        } catch(BodyTooLarge ex) { responder(request,413,"{\"erro\":\"Corpo acima de 8192 bytes\"}"); }
        catch(IllegalArgumentException ex) { responder(request,400,"{\"erro\":"+Json.texto(ex.getMessage())+"}"); }
        catch(Exception ex) { responder(request,500,"{\"erro\":\"Erro interno\"}"); }
    }
    public void iniciar(int porta) throws IOException {
        HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",porta),0);
        var executor=Executors.newFixedThreadPool(2);server.setExecutor(executor);server.createContext("/",this::atender);server.start();
        Runtime.getRuntime().addShutdownHook(new Thread(()->{server.stop(0);executor.shutdownNow();}));
        System.out.println("API_READY http://127.0.0.1:"+server.getAddress().getPort());
        System.out.println("API de tarefas ativa. Use Testar API ou abra /tarefas no navegador. Parar encerra o servidor.");
    }
}

