import { Tarefa } from "./Tarefa";
// Dados em memória: reiniciar a API esvazia a lista.
export class ServicoTarefas {
    private tarefas = new Map<number,Tarefa>();
    private proximoId = 1;
    listar(): Tarefa[] { return [...this.tarefas.values()]; }
    criar(titulo: string): Tarefa {
        const tarefa = new Tarefa(this.proximoId++, titulo);
        this.tarefas.set(tarefa.id, tarefa); return tarefa;
    }
    atualizar(id: number, concluida: boolean): Tarefa | undefined {
        const tarefa = this.tarefas.get(id); if(tarefa) tarefa.concluida = concluida; return tarefa;
    }
    excluir(id: number): boolean { return this.tarefas.delete(id); }
}

