import { ServicoTarefas } from "./ServicoTarefas";
// Tipagem mínima do HTTP nativo do Node. Não requer npm ou @types/node.
interface Requisicao {
    method?: string; url?: string;
    headers: Record<string,string|string[]|undefined>;
    setEncoding(encoding: string): void;
    on(event: "data", fn: (chunk: string) => void): void;
    on(event: "end", fn: () => void): void;
    on(event: "error", fn: (error: Error) => void): void;
}
interface Resposta {
    setHeader(name: string, value: string): void;
    writeHead(status: number): void;
    end(body?: string): void;
}
interface Servidor {
    listen(port: number, host: string, ready: () => void): void;
    address(): { port: number };
    on(event: "error", fn: (error: Error) => void): void;
    requestTimeout: number; headersTimeout: number;
}
declare function require(name: string): { createServer(fn: (req: Requisicao, res: Resposta) => void): Servidor };
declare const process: { exit(code: number): never };

export class ServidorApi {
    constructor(private servico: ServicoTarefas) {}
    iniciar(porta: number): void {
        const http = require("node:http");
        const server = http.createServer((req,res) => this.atender(req,res));
        server.requestTimeout = 5000; server.headersTimeout = 5000;
        server.on("error", error => { console.error(error.message); process.exit(1); });
        server.listen(porta, "127.0.0.1", () => {
            console.log("API_READY http://127.0.0.1:" + server.address().port);
            console.log("API de tarefas ativa. Use Testar API ou abra /tarefas no navegador. Parar encerra o servidor.");
        });
    }
    private responder(res: Resposta, status: number, body?: unknown): void {
        res.setHeader("Content-Type", "application/json; charset=utf-8");
        res.setHeader("Cache-Control", "no-store"); res.setHeader("X-Content-Type-Options", "nosniff");
        res.writeHead(status); res.end(status === 204 ? undefined : JSON.stringify(body));
    }
    private atender(req: Requisicao, res: Resposta): void {
        const method = req.method || "GET";
        const path = new URL(req.url || "/", "http://127.0.0.1").pathname;
        if((path === "/" || path === "/saude") && method === "GET") {
            this.responder(res,200,path === "/saude" ? {status:"ok"} : {api:"Tarefas Trama",rotas:["GET /saude","GET /tarefas","POST /tarefas","PATCH /tarefas/{id}","DELETE /tarefas/{id}"]}); return;
        }
        const collection = path === "/tarefas", item = /^\/tarefas\/[1-9][0-9]{0,8}$/.test(path);
        if(!collection && !item) { this.responder(res,404,{erro:"Rota não encontrada"}); return; }
        if(collection && method === "GET") { this.responder(res,200,this.servico.listar()); return; }
        const id = item ? Number(path.substring(9)) : 0;
        if(item && method === "DELETE") { const removed=this.servico.excluir(id);this.responder(res,removed?204:404,removed?undefined:{erro:"Tarefa não encontrada"});return; }
        if(!((collection && method === "POST") || (item && method === "PATCH"))) {
            res.setHeader("Allow",collection?"GET, POST":"PATCH, DELETE");this.responder(res,405,{erro:"Método não permitido"});return;
        }
        const type=req.headers["content-type"];
        if(typeof type !== "string" || type.split(";")[0].trim().toLowerCase() !== "application/json") {this.responder(res,415,{erro:"Use Content-Type application/json"});return;}
        let body="", size=0, failed=false;
        req.setEncoding("utf8");
        req.on("data",chunk=>{ size+=new TextEncoder().encode(chunk).length;if(size<=8192) body+=chunk; });
        req.on("error",()=>{failed=true;});
        req.on("end",()=>{
            if(failed) return;
            if(size>8192) {this.responder(res,413,{erro:"Corpo acima de 8192 bytes"});return;}
            try {
                const data: unknown=JSON.parse(body);
                if(!data || typeof data!=="object" || Array.isArray(data)) throw new Error("Envie um objeto JSON");
                const object=data as Record<string,unknown>;
                if(collection) {
                    if(Object.keys(object).length!==1 || typeof object.titulo!=="string" || !object.titulo.trim() || object.titulo.trim().length>120) throw new Error("Informe apenas titulo: texto de 1 a 120 caracteres");
                    const tarefa=this.servico.criar(object.titulo.trim());res.setHeader("Location","/tarefas/"+tarefa.id);this.responder(res,201,tarefa);
                } else {
                    if(Object.keys(object).length!==1 || typeof object.concluida!=="boolean") throw new Error("Informe apenas concluida: true ou false");
                    const tarefa=this.servico.atualizar(id,object.concluida);this.responder(res,tarefa?200:404,tarefa || {erro:"Tarefa não encontrada"});
                }
            } catch(error) { this.responder(res,400,{erro:error instanceof Error?error.message:"JSON inválido"}); }
        });
    }
}

