"""Local protocol laboratories. Servers and clients use real wire transports."""
import asyncio, json, ssl, sys, tempfile, subprocess, socket, threading
from pathlib import Path
from contextlib import contextmanager

@contextmanager
def certificates():
    with tempfile.TemporaryDirectory(prefix='trama-tls-') as tmp:
        cert,key=Path(tmp)/'cert.pem',Path(tmp)/'key.pem'
        subprocess.run(['openssl','req','-x509','-newkey','rsa:2048','-nodes','-days','1','-subj','/CN=localhost','-addext','subjectAltName=DNS:localhost,IP:127.0.0.1','-keyout',str(key),'-out',str(cert)],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
        server=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER); server.load_cert_chain(cert,key)
        client=ssl.create_default_context(cafile=str(cert))
        yield server,client,cert,key

def http_lab(protocol, message):
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    from urllib.request import Request,urlopen
    class Handler(BaseHTTPRequestHandler):
        def log_message(self,*args): pass
        def do_POST(self):
            body=json.loads(self.rfile.read(int(self.headers.get('Content-Length','0'))))
            if protocol=='graphql':
                from graphql import build_schema,graphql_sync
                schema=build_schema('type Query { saudacao(nome: String!): String! }')
                schema.get_type('Query').fields['saudacao'].resolve=lambda _,info,nome: 'Olá, '+nome
                result=graphql_sync(schema,body['query'],variable_values=body.get('variables'))
                reply={'data':result.data}
                if result.errors: reply['errors']=[{'message':str(e)} for e in result.errors]
            else: reply={'jsonrpc':'2.0','id':body['id'],'result':body['params']['a']+body['params']['b']}
            data=json.dumps(reply,ensure_ascii=False).encode();self.send_response(200);self.send_header('Content-Type','application/json');self.end_headers();self.wfile.write(data)
        def do_GET(self):
            self.send_response(200);self.send_header('Content-Type','text/event-stream' if protocol=='sse' else 'application/json');self.end_headers()
            self.wfile.write(('event: mensagem\ndata: '+json.dumps({'mensagem':message},ensure_ascii=False)+'\n\n').encode() if protocol=='sse' else json.dumps({'mensagem':message}).encode())
    with certificates() as (tls,client,cert,key):
        server=ThreadingHTTPServer(('127.0.0.1',0),Handler)
        secure=protocol=='https'
        if secure: server.socket=tls.wrap_socket(server.socket,server_side=True)
        thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
        url=('https' if secure else 'http')+'://127.0.0.1:'+str(server.server_port)+'/'
        print('Servidor:',url,flush=True)
        payload=({'query':'query($nome: String!) { saudacao(nome: $nome) }','variables':{'nome':message}} if protocol=='graphql' else {'jsonrpc':'2.0','id':1,'method':'somar','params':{'a':7,'b':5}}) if protocol in ('graphql','jsonrpc') else None
        try:
            request=Request(url,data=json.dumps(payload).encode() if payload else None,headers={'Content-Type':'application/json'})
            with urlopen(request,context=client if secure else None,timeout=8) as response: result=response.read().decode()
            if secure: print('TLS: certificado local verificado')
            return result
        finally: server.shutdown();server.server_close();thread.join()

async def websocket_lab(protocol,message):
    from websockets.asyncio.server import serve
    from websockets.asyncio.client import connect
    with certificates() as (tls,client,cert,key):
        async def echo(ws):
            async for value in ws: await ws.send('Eco: '+value)
        secure=protocol=='wss'
        async with serve(echo,'127.0.0.1',0,ssl=tls if secure else None) as server:
            url=('wss' if secure else 'ws')+'://127.0.0.1:'+str(server.sockets[0].getsockname()[1])
            print('Servidor:',url,flush=True)
            async with connect(url,**({'ssl':client} if secure else {})) as ws:
                await ws.send(message);return await ws.recv()

async def http3_lab(message):
    from aioquic.asyncio import serve,connect,QuicConnectionProtocol
    from aioquic.h3.connection import H3Connection,H3_ALPN
    from aioquic.h3.events import HeadersReceived,DataReceived
    from aioquic.quic.configuration import QuicConfiguration
    class Protocol(QuicConnectionProtocol):
        def __init__(self,*args,**kwargs):
            super().__init__(*args,**kwargs);self.http=H3Connection(self._quic);self.pending={};self.body={}
        def quic_event_received(self,event):
            for item in self.http.handle_event(event):
                if isinstance(item,HeadersReceived) and not self._quic.configuration.is_client:
                    self.http.send_headers(item.stream_id,[(b':status',b'200'),(b'content-type',b'application/json')])
                    self.http.send_data(item.stream_id,json.dumps({'mensagem':message,'protocolo':'h3'}).encode(),end_stream=True);self.transmit()
                elif isinstance(item,DataReceived) and item.stream_id in self.pending:
                    self.body[item.stream_id]+=item.data
                    if item.stream_ended: self.pending.pop(item.stream_id).set_result(self.body.pop(item.stream_id).decode())
    with certificates() as (tls,client,cert,key):
        config=QuicConfiguration(is_client=False,alpn_protocols=H3_ALPN);config.load_cert_chain(cert,key)
        server=await serve('127.0.0.1',0,configuration=config,create_protocol=Protocol)
        port=server._transport.get_extra_info('sockname')[1]
        try:
            configuration=QuicConfiguration(is_client=True,alpn_protocols=H3_ALPN);configuration.load_verify_locations(str(cert))
            async with connect('127.0.0.1',port,configuration=configuration,create_protocol=Protocol) as connection:
                stream=connection._quic.get_next_available_stream_id();future=asyncio.get_running_loop().create_future();connection.pending[stream]=future;connection.body[stream]=b''
                connection.http.send_headers(stream,[(b':method',b'GET'),(b':scheme',b'https'),(b':authority',b'localhost'),(b':path',b'/')],end_stream=True);connection.transmit()
                print('HTTP/3 real: QUIC / UDP / TLS 1.3, porta',port,flush=True)
                return await asyncio.wait_for(future,10)
        finally: server.close()

